import { defineCollection } from "astro:content";
import { glob } from "astro/loaders";
import { z } from "astro/zod";

import { transcriptionSchema } from "./transcriptions";

export const collections = {
  issues: defineCollection({
    loader: glob({ pattern: "**/[^_]*.{md,mdx}", base: "./src/data/issues" }),
    schema: z.object({
      title: z.string(),
      date: z.coerce.date(),
      link: z.url(),
      images: z.array(z.url()),
      tags: z.array(z.string()),
    }),
  }),
  // Generated by the OCR pipeline (src/scripts/ocr), one file per page at
  // <issue-id>/<page>.json. The entry id is "<issue-id>/<page>", where
  // <issue-id> is the id of the entry in `issues`.
  transcriptions: defineCollection({
    loader: glob({
      pattern: "*/*.json",
      base: "./src/data/transcriptions",
      generateId: ({ data }) => `${data["issueId"]}/${data["page"]}`,
    }),
    schema: transcriptionSchema,
  }),
};
